#!/bin/bash
set -e
cd /home/user

ls /home/user/api_diagnostics/
head -20 /home/user/api_diagnostics/auth_events.log
head -20 /home/user/api_diagnostics/latency_samples.csv
head -20 /home/user/api_diagnostics/error_counts.tsv
head -20 /home/user/api_diagnostics/system_metrics.log
wc -l /home/user/api_diagnostics/auth_events.log /home/user/api_diagnostics/latency_samples.csv /home/user/api_diagnostics/error_counts.tsv /home/user/api_diagnostics/system_metrics.log
printf '%s\n' 'import csv,sys' 'from collections import defaultdict' '' 'auth_total=auth_ok=auth_fail=0' 'fail_counts=defaultdict(int)' 'for line in open("/home/user/api_diagnostics/auth_events.log"):' '    parts=line.split()' '    if not parts: continue' '    auth_total+=1' '    user=next((p.split("=",1)[1] for p in parts if p.startswith("user=")),None)' '    result=next((p.split("=",1)[1] for p in parts if p.startswith("result=")),None)' '    if result=="OK": auth_ok+=1' '    elif result=="FAIL": auth_fail+=1; fail_counts[user]+=1' 'top_fail_user=max(fail_counts,key=fail_counts.get)' 'top_fail_count=fail_counts[top_fail_user]' > /tmp/analyze.py
printf '%s\n' 'latencies=[]' 'ep_lat=defaultdict(list)' 'http200=0' 'for row in csv.DictReader(open("/home/user/api_diagnostics/latency_samples.csv")):' '    lat=float(row["latency_ms"]); ep=row["endpoint"]; sc=int(row["status_code"])' '    latencies.append(lat); ep_lat[ep].append(lat)' '    if sc==200: http200+=1' 'lat_min=int(min(latencies)); lat_max=int(max(latencies))' 'lat_mean=round(sum(latencies)/len(latencies),1)' 'ep_means={ep:sum(v)/len(v) for ep,v in ep_lat.items()}' 'slowest_ep=max(ep_means,key=ep_means.get)' 'slowest_avg=round(ep_means[slowest_ep],1)' >> /tmp/analyze.py
printf '%s\n' 'total_errors=0' 'ep_errors=defaultdict(int)' 'worst_ts=None; worst_cnt=-1' 'for line in open("/home/user/api_diagnostics/error_counts.tsv"):' '    p=line.strip().split("\t"); ts,ep,cnt=p[0],p[1],int(p[2])' '    total_errors+=cnt; ep_errors[ep]+=cnt' '    if cnt>worst_cnt or (cnt==worst_cnt and ts<worst_ts): worst_cnt=cnt; worst_ts=ts' 'most_err_ep=max(ep_errors,key=ep_errors.get)' 'most_err_cnt=ep_errors[most_err_ep]' >> /tmp/analyze.py
printf '%s\n' 'cpu_vals=[]; mem_vals=[]' 'for line in open("/home/user/api_diagnostics/system_metrics.log"):' '    parts=line.split()' '    cpu=float(next(p.split("=",1)[1] for p in parts if p.startswith("cpu_pct=")))' '    mem=float(next(p.split("=",1)[1] for p in parts if p.startswith("mem_pct=")))' '    cpu_vals.append(cpu); mem_vals.append(mem)' 'peak_cpu=max(cpu_vals); peak_mem=max(mem_vals)' 'high_cpu=sum(1 for c in cpu_vals if c>80.0)' >> /tmp/analyze.py
printf '%s\n' 'out=open("/home/user/api_diagnostics/diagnostic_report.txt","w")' 'out.write("=== API DIAGNOSTIC REPORT ===\n\n")' 'out.write("--- AUTH EVENTS ---\n")' 'out.write(f"Total events: {auth_total}\n")' 'out.write(f"Successful: {auth_ok}\n")' 'out.write(f"Failed: {auth_fail}\n")' 'out.write(f"Top failing user: {top_fail_user} ({top_fail_count} failures)\n")' 'out.write("\n--- LATENCY (ms) ---\n")' 'out.write(f"Min: {lat_min}\n")' 'out.write(f"Max: {lat_max}\n")' 'out.write(f"Mean: {lat_mean}\n")' 'out.write(f"Slowest endpoint: {slowest_ep} (avg {slowest_avg}ms)\n")' 'out.write(f"HTTP 200 count: {http200}\n")' 'out.write("\n--- ERROR COUNTS ---\n")' 'out.write(f"Total errors: {total_errors}\n")' 'out.write(f"Most errors endpoint: {most_err_ep} ({most_err_cnt} errors)\n")' 'out.write(f"Worst minute: {worst_ts} ({worst_cnt} errors)\n")' 'out.write("\n--- SYSTEM METRICS ---\n")' 'out.write(f"Peak CPU: {peak_cpu}%\n")' 'out.write(f"Peak Memory: {peak_mem}%\n")' 'out.write(f"High CPU samples (>80%): {high_cpu}\n")' 'out.close()' >> /tmp/analyze.py
python3 /tmp/analyze.py
